def build_tree(tokens: list[Token]) -> Document:
    document = Document()
    stack: list[Document | Element] = [document]
    for token in tokens:
        if isinstance(token, StartTag):
            element = Element(tag=token.name)
            stack[-1].children.append(element)
            stack.append(element)
