    mode: str | None = None
    query_value: str | None = None
    inspect_tokens = False
    files: list[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--tokens":
            inspect_tokens = True
        elif arg in ("--tree", "--text"):
            mode = arg[2:]
        elif arg in ("--find-tag", "--find-id", "--find-class"):
